PRAGMA foreign_keys = ON;

CREATE TABLE schema_migrations (version TEXT PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE books (book_id TEXT PRIMARY KEY, title TEXT NOT NULL, current_brief_version INTEGER, current_canon_version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE chapters (chapter_id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES books(book_id), chapter_number INTEGER NOT NULL, title TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(book_id, chapter_number));
CREATE TABLE scenes (scene_id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES books(book_id), chapter_id TEXT NOT NULL REFERENCES chapters(chapter_id), scene_number INTEGER NOT NULL, current_scene_state TEXT, current_scene_state_report_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(chapter_id, scene_number));

CREATE TABLE creative_briefs (brief_id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES books(book_id), brief_version INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','confirmed','superseded')), payload_json TEXT NOT NULL, content_hash TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(book_id, brief_version));
CREATE TABLE scene_plans (plan_id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES books(book_id), chapter_id TEXT NOT NULL REFERENCES chapters(chapter_id), scene_id TEXT NOT NULL REFERENCES scenes(scene_id), plan_version INTEGER NOT NULL, brief_version INTEGER NOT NULL, story_state_version INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','validated','ready','superseded')), payload_json TEXT NOT NULL, content_hash TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(scene_id, plan_version));
CREATE TABLE context_packs (context_pack_id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES books(book_id), chapter_id TEXT NOT NULL REFERENCES chapters(chapter_id), scene_id TEXT NOT NULL REFERENCES scenes(scene_id), context_pack_version INTEGER NOT NULL, target_agent TEXT NOT NULL, target_node TEXT NOT NULL, plan_version INTEGER NOT NULL, content_hash TEXT NOT NULL, payload_json TEXT NOT NULL, assembled_at TEXT NOT NULL, UNIQUE(scene_id, context_pack_version, target_agent, target_node));
CREATE TABLE prose_drafts (draft_id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES books(book_id), chapter_id TEXT NOT NULL REFERENCES chapters(chapter_id), scene_id TEXT NOT NULL REFERENCES scenes(scene_id), draft_version INTEGER NOT NULL, attempt INTEGER NOT NULL CHECK(attempt > 0), plan_version INTEGER NOT NULL, context_pack_version INTEGER NOT NULL, text TEXT NOT NULL, word_count INTEGER NOT NULL CHECK(word_count >= 0), target_word_count INTEGER NOT NULL CHECK(target_word_count > 0), complete INTEGER NOT NULL CHECK(complete IN (0,1)), writer_self_check_json TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('generated','in_review','passed','failed','superseded')), draft_hash TEXT NOT NULL, harness_call_id TEXT, content_attempt_in_plan INTEGER NOT NULL, content_attempt_total INTEGER NOT NULL, created_at TEXT NOT NULL, UNIQUE(scene_id, draft_version));
CREATE TABLE quality_reports (report_id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES books(book_id), chapter_id TEXT NOT NULL REFERENCES chapters(chapter_id), scene_id TEXT NOT NULL REFERENCES scenes(scene_id), draft_id TEXT NOT NULL REFERENCES prose_drafts(draft_id), draft_hash TEXT NOT NULL, review_attempt INTEGER NOT NULL, review_completion_status TEXT NOT NULL CHECK(review_completion_status IN ('pending','completed','partial','failed')), reviewer_results_json TEXT NOT NULL, deduped_issue_count INTEGER NOT NULL DEFAULT 0, ordinary_issue_count INTEGER NOT NULL DEFAULT 0, serious_issue_count INTEGER NOT NULL DEFAULT 0, has_true_conflict INTEGER NOT NULL CHECK(has_true_conflict IN (0,1)), needs_arbiter INTEGER NOT NULL CHECK(needs_arbiter IN (0,1)), routing_recommendation TEXT NOT NULL, accepted_scene_state_json TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('passed','failed','needs_arbiter')), created_at TEXT NOT NULL, UNIQUE(scene_id, draft_id, review_attempt));
CREATE TABLE memory_proposals (proposal_id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES books(book_id), chapter_id TEXT NOT NULL REFERENCES chapters(chapter_id), scene_id TEXT NOT NULL REFERENCES scenes(scene_id), source_draft_id TEXT NOT NULL REFERENCES prose_drafts(draft_id), source_report_id TEXT NOT NULL REFERENCES quality_reports(report_id), proposal_version INTEGER NOT NULL, memory_type TEXT NOT NULL, target_scope TEXT NOT NULL, target_key TEXT NOT NULL, action TEXT NOT NULL CHECK(action IN ('create','update','delete')), before_value_json TEXT, after_value_json TEXT, evidence TEXT NOT NULL, evidence_location TEXT NOT NULL, change_reason TEXT NOT NULL, conflict_status TEXT NOT NULL CHECK(conflict_status IN ('none','conflict','resolved')), write_policy TEXT NOT NULL CHECK(write_policy IN ('auto_save','human_confirmation','never_auto_write')), status TEXT NOT NULL CHECK(status IN ('pending','approved','rejected','written','conflict')), created_at TEXT NOT NULL, UNIQUE(scene_id, proposal_version, target_key));
CREATE TABLE task_states (task_id TEXT PRIMARY KEY, task_scope TEXT NOT NULL CHECK(task_scope IN ('book','chapter','scene')), book_id TEXT NOT NULL REFERENCES books(book_id), chapter_id TEXT REFERENCES chapters(chapter_id), scene_id TEXT REFERENCES scenes(scene_id), current_node TEXT NOT NULL, status TEXT NOT NULL, next_action TEXT NOT NULL, plan_attempt INTEGER NOT NULL DEFAULT 1, content_attempt_in_plan INTEGER NOT NULL DEFAULT 0, content_attempt_total INTEGER NOT NULL DEFAULT 0, technical_retry_count INTEGER NOT NULL DEFAULT 0, active_contract_refs_json TEXT NOT NULL, pause_reason TEXT, block_reason TEXT, exception_id TEXT, skip_record_json TEXT, idempotency_key TEXT NOT NULL UNIQUE, run_lock_json TEXT, state_version INTEGER NOT NULL DEFAULT 1, state_history_json TEXT NOT NULL, last_error_json TEXT, execution_mode TEXT NOT NULL DEFAULT 'sequential' CHECK(execution_mode IN ('sequential','independent_test')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX one_running_task_per_scene ON task_states(scene_id) WHERE scene_id IS NOT NULL AND status IN ('queued','running','reworking_writing','reworking_planning','exception_pending','exception_handling');

CREATE TABLE task_events (event_id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES task_states(task_id), event_type TEXT NOT NULL, from_node TEXT, from_status TEXT, to_node TEXT, to_status TEXT, payload_json TEXT NOT NULL, actor_id TEXT, reason TEXT, created_at TEXT NOT NULL);
CREATE TABLE exception_queue (exception_id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES task_states(task_id), source_node TEXT NOT NULL, error_code TEXT NOT NULL, error_message TEXT NOT NULL, details_json TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','handling','resolved','failed')), retry_count INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, resolved_at TEXT);
CREATE TABLE harness_calls (harness_call_id TEXT PRIMARY KEY, task_id TEXT REFERENCES task_states(task_id), agent_type TEXT NOT NULL, provider TEXT, model TEXT, request_json TEXT NOT NULL, response_json TEXT, status TEXT NOT NULL, error_json TEXT, started_at TEXT NOT NULL, completed_at TEXT);
CREATE TABLE memory_records (memory_record_id TEXT PRIMARY KEY, book_id TEXT REFERENCES books(book_id), scene_id TEXT REFERENCES scenes(scene_id), target_scope TEXT NOT NULL, memory_type TEXT NOT NULL, target_key TEXT NOT NULL, value_json TEXT NOT NULL, source_proposal_id TEXT REFERENCES memory_proposals(proposal_id), approval_status TEXT NOT NULL CHECK(approval_status IN ('pending','approved','rejected')), version INTEGER NOT NULL, created_at TEXT NOT NULL, UNIQUE(target_scope, book_id, scene_id, target_key, version));

INSERT OR IGNORE INTO schema_migrations(version) VALUES ('001_initial');
